-- REVIEW ONLY. One CREATE OR REPLACE statement. Execute as SQL script in DBeaver.
USE auxiliares;
DELIMITER $$
CREATE OR REPLACE TRIGGER `TRG_FB_CONTACTOS_HIST_ALTA` AFTER INSERT ON `FB_CONTACTOS` FOR EACH ROW
BEGIN
IF NEW.VERSION<>1 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_VERSION_INICIAL'; END IF;
IF EXISTS (SELECT 1 FROM FB_CIU_CONSULTAS_WEB WHERE ID_PERSONA=NEW.ID_PERSONA AND ID_CONSULTA>NEW.ID_CONSULTA) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='71_ORIGEN_ANTIGUO'; END IF;
INSERT INTO FB_CONTACTOS_HISTORIAL (ID_CONTACTO,ID_CONSULTA,VERSION,USUARIO_MODIFICADOR_ID,DATOS_ANTERIORES,DATOS_NUEVOS) VALUES (NEW.ID_CONTACTO,NEW.ID_CONSULTA,NEW.VERSION,NEW.USUARIO_MODIFICADOR_ID,NULL,JSON_OBJECT('id_contacto',CAST(NEW.`ID_CONTACTO` AS CHAR),'id_consulta',CAST(NEW.`ID_CONSULTA` AS CHAR),'telefono_1',NEW.`TELEFONO_1`,'tipo_telefono_1',NEW.`TIPO_TELEFONO_1`,'telefono_2',NEW.`TELEFONO_2`,'tipo_telefono_2',NEW.`TIPO_TELEFONO_2`,'telefono_3',NEW.`TELEFONO_3`,'tipo_telefono_3',NEW.`TIPO_TELEFONO_3`,'telefono_4',NEW.`TELEFONO_4`,'tipo_telefono_4',NEW.`TIPO_TELEFONO_4`,'telefono_5',NEW.`TELEFONO_5`,'tipo_telefono_5',NEW.`TIPO_TELEFONO_5`,'mail_1',NEW.`MAIL_1`,'mail_2',NEW.`MAIL_2`,'mail_3',NEW.`MAIL_3`,'mail_4',NEW.`MAIL_4`,'mail_5',NEW.`MAIL_5`,'fecha_alta',NEW.`FECHA_ALTA`,'nombre_completo',NEW.`NOMBRE_COMPLETO`,'tipo_documento',NEW.`TIPO_DOCUMENTO`,'documento',NEW.`DOCUMENTO`,'documento_normalizado',NEW.`DOCUMENTO_NORMALIZADO`,'usuario_modificador_id',NEW.`USUARIO_MODIFICADOR_ID`,'fecha_modificacion',NEW.`FECHA_MODIFICACION`,'version',NEW.`VERSION`,'id_persona',CAST(NEW.`ID_PERSONA` AS CHAR)));
END$$
DELIMITER ;
